// Copyright 2026 ReC Sandbox. Distributed under the terms in LICENSE.md at the repository root.#pragma once// The controls the CineCam Grade panel is made of (S10 item 5). Nothing here knows about// entities, components or undo - each control owns a number, says when a gesture starts, while it// runs and when it ends, and the panel turns that into one undo transaction (CineGradeBinding.h).//// The three signals are the shape PropertyRowNumberField uses for a slider drag// (Serialization/PropertyTreeLegacy/PropertyRowNumberField.cpp:49-115): open the transaction on// the press, change the value as often as the mouse moves, close it on the release.#include <QWidget>#include <QImage>#include <QPointF>#include <CryMath/Cry_Math.h>class QDoubleSpinBox;class QLabel;class QSlider;namespace CineCamGrade{//! A hue/saturation disc: direction = hue, distance from the centre = strength, centre = neutral.//! It carries the mean-free part of an RGB triple, so it changes the COLOUR of a band and never//! its level - that is what the master beside it is for.class CCineWheelDisc : public QWidget{	Q_OBJECTpublic:	explicit CCineWheelDisc(QWidget* pParent = nullptr);	//! Per-channel deviation at the rim of the disc. Lift wants a smaller one than Gain.	void  SetAmplitude(float amplitude) { m_amplitude = amplitude; }	//! The channel deviations from neutral. Only the mean-free part is shown; the numeric fields	//! next to the disc remain the truth for anything else.	void  SetDeviation(const Vec3& deviation);	Vec3  GetDeviation() const;	//! The width comes from the dock (the size policy is Expanding), the height is set to match by	//! the control that owns the disc - that is what keeps it a circle at any dock width.	QSize sizeHint() const override { return QSize(128, 128); }	QSize minimumSizeHint() const override { return QSize(64, 64); }signals:	void SignalBeginEdit();	void SignalChanged();	void SignalEndEdit();protected:	void paintEvent(QPaintEvent* pEvent) override;	void resizeEvent(QResizeEvent* pEvent) override;	void mousePressEvent(QMouseEvent* pEvent) override;	void mouseMoveEvent(QMouseEvent* pEvent) override;	void mouseReleaseEvent(QMouseEvent* pEvent) override;	void mouseDoubleClickEvent(QMouseEvent* pEvent) override;private:	void   SetFromPos(const QPoint& pos);	void   Reset();	QRectF DiscRect() const;	//! Normalised puck position, y up, length clamped to 1.	QPointF m_pos = QPointF(0.0, 0.0);	float   m_amplitude = 0.5f;	bool    m_dragging = false;	QImage  m_wheelImage;};//! Disc + master + the four numbers, i.e. one of the three Primaries wheels.class CCineWheelControl : public QWidget{	Q_OBJECTpublic:	//! neutral: 0 for Lift (the master is additive), 1 for Gamma and Gain (multiplicative).	CCineWheelControl(const QString& title, float neutral, float amplitude,	                  float masterMin, float masterMax, float masterNeutral, QWidget* pParent = nullptr);	void  SetValues(const Vec3& rgb, float master);	Vec3  GetRgb() const    { return m_rgb; }	float GetMaster() const { return m_master; }	void  SetReadOnly(bool bReadOnly);signals:	void SignalBeginEdit();	void SignalChanged();	void SignalEndEdit();protected:	void resizeEvent(QResizeEvent* pEvent) override;private:	//! Square the disc against the width this control was actually given.	void UpdateDiscSize();	void OnDiscChanged();	void OnSpinChanged();	void OnMasterSliderChanged(int value);	void OnMasterSpinChanged(double value);	void ResetAll();	void RefreshWidgets();	CCineWheelDisc* m_pDisc = nullptr;	QDoubleSpinBox* m_pChannel[3] = { nullptr, nullptr, nullptr };	QSlider*        m_pMasterSlider = nullptr;	QDoubleSpinBox* m_pMasterSpin = nullptr;	Vec3  m_rgb;	float m_master = 0.0f;	const float m_neutral;	const float m_masterMin;	const float m_masterMax;	const float m_masterNeutral;	bool m_updating = false;};//! Label + slider + numeric field, for the single floats (contrast, pivot, saturation, the ten//! curve controls). The slider is the coarse gesture, the field is the exact number.class CCineFloatRow : public QWidget{	Q_OBJECTpublic:	CCineFloatRow(const QString& label, float minValue, float maxValue, float neutral,	              int decimals, QWidget* pParent = nullptr);	void  SetValue(float value);	float GetValue() const { return m_value; }	void  SetReadOnly(bool bReadOnly);signals:	void SignalBeginEdit();	void SignalChanged();	void SignalEndEdit();private:	void OnSliderChanged(int value);	void OnSpinChanged(double value);	void RefreshWidgets();	QSlider*        m_pSlider = nullptr;	QDoubleSpinBox* m_pSpin = nullptr;	float m_value = 0.0f;	const float m_min;	const float m_max;	const float m_neutral;	bool m_updating = false;};} // namespace CineCamGrade